  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

{
  "meta": {
    "version": 1,
    "generated": "R8-cand-flash",
    "captain": "Captain dispatches QM against these targets"
  },
  "watches": [
    {
      "id": "visibility",
      "label": "Main/footer visibility when no todos",
      "scenarios": [
