const { Given, When, Then } = require('@cucumber/cucumber');

// ── Background ──────────────────────────────────────────────────

Given('the app is loaded', function () {
  // world.js Before hook already loads the app via loadApp()
  // This step exists as a readable declaration; the actual work
  // happens in the Before hook.
});

// ── Helpers ─────────────────────────────────────────────────────

function queryAll(root, selector) {
  if (!root) return [];
  const result = root.querySelectorAll(selector);
  return Array.from(result);
}

function query(root, selector) {
  return root ? root.querySelector(selector) : null;
}

function todoItems() {
  const list = this.document.querySelector('.todo-list');
  if (!list) return [];
  return Array.from(list.querySelectorAll('li'));
}

function firstTodo() {
  const items = todoItems.call(this);
  return items.length > 0 ? items[0] : null;
}

function getVisible(el) {
  if (!el) return 'none';
  const style = this.window.getComputedStyle(el);
  return style.display;
}

function isVisible(el) {
  if (!el) return false;
  const style = this.window.getComputedStyle(el);
  // A hidden element has display:none or its offsetParent is null
  return style.display !== 'none' && style.visibility !== 'hidden';
}

function todoTitle(el) {
  const label = el.querySelector('label');
  return label ? label.textContent.trim() : '';
}

function todoCompleted(el) {
  return el.classList.contains('completed');
}

// ── No todos ────────────────────────────────────────────────────

Given('there are no todos', function () {
  // Clear localStorage and reinitialise the app state
  this.window.localStorage.removeItem('todos-vanillajs');
  // Reload the page to start fresh
  this.document.location.reload();
  // Reinitialize app by dispatching init events
  this.document.dispatchEvent(new this.window.Event('DOMContentLoaded', { bubbles: true }));
  this.window.dispatchEvent(new this.window.Event('load'));
});

Then('{string} is not visible', function (selector) {
  const el = query(this.document, selector);
  if (!el) return; // element not in DOM = not visible
  const visible = isVisible.call(this, el);
  if (visible) {
    throw new Error(`Expected "${selector}" to not be visible, but it is visible`);
  }
});

// ── New todo ────────────────────────────────────────────────────

When('I type {string} into {string}', function (text, selector) {
  const input = query(this.document, selector);
  if (!input) throw new Error(`Input "${selector}" not found`);
  input.value = text;
  // Dispatch input event so app can react
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press Enter', function () {
  const input = this.document.querySelector('.new-todo');
  if (!input) throw new Error('New todo input not found');
  const ev = new this.window.KeyboardEvent('keypress', { key: 'Enter', keyCode: 13, which: 13, bubbles: true });
  input.dispatchEvent(ev);
  // Also dispatch keydown/keyup for compatibility
  const ev2 = new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, which: 13, bubbles: true });
